// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testFuzz_property(address newLog) public {
        vm.assume(newLog != address(0));

        LogHelper orig = new LogHelper();
        c.SetLogFile(address(orig));

        c.Initialized();

        bool ok;
        try c.SetLogFile(newLog) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract LogHelper {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message public LastMsg;
    function AddMessage(address _adr,uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
